'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];

const UI_SPECIAL={qbittorrent:'qBittorrent',github:'GitHub',api:'API',ip:'IP',cidr:'CIDR',qr:'QR',url:'URL',lan:'LAN',nic:'NIC',https:'HTTPS',http:'HTTP',ui:'UI',pwa:'PWA',exe:'EXE',eta:'ETA',id:'ID',pc:'PC',nas:'NAS',ntfy:'ntfy',sonarr:'Sonarr',radarr:'Radarr',lidarr:'Lidarr',prowlarr:'Prowlarr',jellyfin:'Jellyfin',plex:'Plex',discord:'Discord',windows:'Windows'};
function uiText(value=''){let s=String(value||'');if(!s)return s;const ell=s.endsWith('…');if(ell)s=s.slice(0,-1);s=s.replace(/qBittorrent/g,'QBITTORRENT').replace(/GitHub/g,'GITHUB');s=s.replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/([A-Za-z])([0-9])/g,'$1 $2').replace(/([0-9])([A-Za-z])/g,'$1 $2').replace(/[_-]+/g,' ');s=s.split(/\s+/).filter(Boolean).map(w=>UI_SPECIAL[w.toLowerCase()]||(/^\d/.test(w)?w:w.charAt(0).toUpperCase()+w.slice(1))).join(' ');return s+(ell?'…':'')}
function applyTitleCaseUi(root=document){const selectors='button,label,th,h1,h2,h3,.panel-title,.settings-section-title,.eyebrow,.nav,.mobile-nav,.detail-tabs,legend,.metric span,.field-row b,.dependency-card b,.dependency-card strong,.review-grid span,.update-status span';const els=[];if(root.matches?.(selectors))els.push(root);els.push(...(root.querySelectorAll?.(selectors)||[]));els.forEach(el=>{for(const n of [...el.childNodes]){if(n.nodeType===Node.TEXT_NODE){const raw=n.nodeValue,trim=raw.trim();if(trim&&trim.length<80&&!/[.!?]$/.test(trim)&&/[A-Za-z]/.test(trim)){n.nodeValue=raw.replace(trim,uiText(trim))}}}})}
const titleObserver=new MutationObserver(records=>{for(const r of records){for(const n of r.addedNodes){if(n.nodeType===Node.ELEMENT_NODE)applyTitleCaseUi(n)}}});

const state={me:null,csrf:'',setup:null,setupStep:0,setupMaxStep:0,server:'all',torrents:[],transfer:{},meta:{},filter:localStorage.tdFilter||'all',sort:localStorage.tdSort||'added_desc',search:localStorage.tdSearch||'',category:localStorage.tdCategory||'',tag:localStorage.tdTag||'',tracker:localStorage.tdTracker||'',selected:new Set(),detail:null,detailTab:'overview',refreshMs:2000,settings:null,lastComplete:new Set(),deferredPrompt:null,setupInterfaceSelectionInitialized:false,settingsInterfaceSelectionInitialized:false,updateInfo:null};

function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function bytes(n,d=1){n=Number(n);if(!Number.isFinite(n)||n<0)return'—';if(n===0)return'0 B';const u=['B','KB','MB','GB','TB','PB'];let i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);return`${(n/1024**i).toFixed(i?d:0)} ${u[i]}`}
function speed(n){return`${bytes(n)}/s`}
function eta(s){s=Number(s);if(!Number.isFinite(s)||s<0||s>=8640000)return'∞';let d=Math.floor(s/86400);s%=86400;let h=Math.floor(s/3600);s%=3600;let m=Math.floor(s/60);if(d)return`${d}d ${h}h`;if(h)return`${h}h ${m}m`;if(m)return`${m}m`;return`${Math.floor(s)}s`}
function when(ts){if(!ts)return'—';const d=new Date(Number(ts)*1000);return d.toLocaleString()}
function rel(ts){if(!ts)return'—';let s=Math.max(0,Date.now()/1000-ts);if(s<60)return`${Math.floor(s)}s ago`;if(s<3600)return`${Math.floor(s/60)}m ago`;if(s<86400)return`${Math.floor(s/3600)}h ago`;return`${Math.floor(s/86400)}d ago`}
function toast(msg,type=''){const el=document.createElement('div');el.className='toast '+type;el.textContent=/^[A-Za-z0-9_ -]+$/.test(String(msg))?uiText(msg):msg;$('#toasts').append(el);setTimeout(()=>el.remove(),3800)}
function beep(){if(!state.settings?.notifications?.sound)return;try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.frequency.value=720;g.gain.value=.035;o.connect(g);g.connect(c.destination);o.start();setTimeout(()=>{o.stop();c.close()},120)}catch{}}
async function api(url,opt={}){opt.headers={...(opt.headers||{})};if(opt.method&&opt.method!=='GET'&&opt.method!=='HEAD'&&state.csrf)opt.headers['X-CSRF-Token']=state.csrf;const r=await fetch(url,opt);let data;const ct=r.headers.get('content-type')||'';data=ct.includes('json')?await r.json():await r.text();if(r.status===401){showLogin();throw new Error(data.error||'Authentication required')}if(!r.ok)throw new Error(data.error||`HTTP ${r.status}`);return data}
async function post(url,obj){return api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(obj)})}

function showLogin(){
  $('#setup').classList.add('hidden');$('#app').classList.add('hidden');$('#login').classList.remove('hidden');
  $('#loginUser').value='';$('#loginPass').value='';
}
function showApp(){ $('#setup').classList.add('hidden');$('#login').classList.add('hidden');$('#app').classList.remove('hidden') }
function showSetup(){ $('#login').classList.add('hidden');$('#app').classList.add('hidden');$('#setup').classList.remove('hidden') }

async function rawJson(url,opt={}){const r=await fetch(url,opt);const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||`HTTP ${r.status}`);return data}
function parseWhitelist(selector){return $(selector).value.split(/\n|,/).map(x=>x.trim()).filter(Boolean)}
function selectedInterfaceIds(target){return $$(`${target} input[data-interface-id]:checked`).map(x=>x.dataset.interfaceId)}
function setupServer(){return{type:'qbittorrent',name:$('#wClientName').value.trim()||'qBittorrent',base_url:$('#wClientUrl').value.trim(),auth_method:$('#wClientAuth').value,api_key:$('#wClientApiKey').value.trim(),username:$('#wClientUser').value.trim(),password:$('#wClientPass').value,enabled:true}}
function setupPayload(){return{setup_code:$('#wSetupCode').value.trim(),dashboard:{title:$('#wTitle').value.trim()||'Torrent Desk',port:Number(state.setup?.port||8765),refresh_seconds:Number($('#wRefresh').value||2),read_only:$('#wReadOnly').checked},updates:{enabled:$('#wUpdatesEnabled').checked,repository:$('#wUpdateRepo').value.trim(),github_token:$('#wUpdateToken').value.trim(),auto_check:$('#wUpdateAutoCheck').checked,check_hours:6},auth:{mode:$('#wAuthMode').value,username:$('#wDashUser').value.trim()||'admin',password:$('#wDashPass').value,trusted_interfaces:selectedInterfaceIds('#wInterfaceList'),trusted_ips:parseWhitelist('#wTrustedIps')},servers:[setupServer()]}}

function interfaceCard(item,checked){const label=item.interface||item.interface_id||'Network Interface',gateway=item.gateway?` · gateway ${esc(item.gateway)}`:'',def=item.default?'<span class="interface-default">defaultRoute</span>':'';return`<label class="interface-card"><input type="checkbox" data-interface-id="${esc(item.interface_id||item.interface||'')}" ${checked?'checked':''}><div><div class="interface-title"><b>${esc(label)}</b>${def}</div><span>${esc(item.address||'—')} · ${esc(item.cidr||uiText('unknownSubnet'))}${gateway}</span><small>${esc(item.netmask||'')} ${item.range_start?`· ${esc(item.range_start)}–${esc(item.range_end)}`:''}</small></div></label>`}
function renderInterfaceList(target,interfaces,selected=[],autoSelectDefault=false){const el=$(target);if(!el)return;interfaces=interfaces||[];const selectedSet=new Set(selected||[]);if(autoSelectDefault&&!selectedSet.size&&interfaces.length){const d=interfaces.find(x=>x.default)||interfaces[0];if(d)selectedSet.add(d.interface_id||d.interface)}if(!interfaces.length){el.innerHTML='<div class="interface-empty"><b>noNetworkInterfacesDetected</b><span>You can still use the IP address whitelist below.</span></div>';return}el.innerHTML=interfaces.map(x=>interfaceCard(x,selectedSet.has(x.interface_id||x.interface))).join('')}
async function refreshSetupInterfaces(force=false){const current=selectedInterfaceIds('#wInterfaceList');const d=await rawJson(`/api/setup/network-interfaces?refresh=${force?'1':'0'}`);state.setup.network_interfaces=d.interfaces||[];renderInterfaceList('#wInterfaceList',state.setup.network_interfaces,current,current.length===0&&!state.setupInterfaceSelectionInitialized);state.setupInterfaceSelectionInitialized=true}
async function refreshSettingsInterfaces(force=false){const current=selectedInterfaceIds('#sInterfaceList');const d=await api(`/api/network/interfaces?refresh=${force?'1':'0'}`);if(state.settings?.runtime)state.settings.runtime.network_interfaces=d.interfaces||[];renderInterfaceList('#sInterfaceList',d.interfaces||[],current,false)}

function renderDependencyStatus(target,status){const el=$(target);if(!el)return;status=status||{};const defs=[['qr','qrCodes','Generate the LAN access QR code.'],['tray','windowsTray','Run Torrent Desk from the Windows system tray.'],['windowsService','windowsService','Install and run as a Windows service.'],['exeBuilder','exeBuilder','Build a self-contained Windows executable.']];el.innerHTML=defs.map(([key,label,desc])=>{const v=status[key]||{},supported=v.supported!==false,installed=!!v.installed;return`<div class="dependency-card ${installed?'installed':''} ${supported?'':'unsupported'}"><div><b>${label}</b><span>${desc}</span><small>${esc((v.packages||[]).join(' + '))}</small></div><strong>${!supported?'notSupported':installed?'installed':'notInstalled'}</strong></div>`}).join('')}
async function installSetupDependency(feature){const out=$('#wDependencyResult'),buttons=[$('#wInstallQr'),$('#wInstallAll')];buttons.forEach(b=>b.disabled=true);out.className='test-result muted';out.textContent=uiText('installingDependencies…');try{const d=await rawJson('/api/setup/install-dependency',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({setup_code:$('#wSetupCode').value.trim(),feature})});state.setup.dependencies=d.status||{};renderDependencyStatus('#wDependencyList',state.setup.dependencies);out.className='test-result ok';out.textContent=uiText('dependenciesInstalled')}catch(e){out.className='test-result bad';out.textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}}

function updateSetupStep(){const pages=$$('.setup-page'),items=$$('#setupSteps li'),last=pages.length-1;state.setupMaxStep=Math.max(state.setupMaxStep,state.setupStep);pages.forEach((p,i)=>p.classList.toggle('active',i===state.setupStep));items.forEach((x,i)=>{x.classList.toggle('active',i===state.setupStep);x.classList.toggle('done',i<state.setupMaxStep);const b=x.querySelector('[data-setup-step]');if(b){b.setAttribute('aria-current',i===state.setupStep?'step':'false');b.title=uiText(i===state.setupStep?'currentStep':'goToSetupStep')}});$('#wBack').classList.toggle('hidden',state.setupStep===0);$('#wNext').textContent=uiText(state.setupStep===last?'finish':'next');if(state.setupStep===last)renderSetupReview();$('#setupError').textContent=''}
function validateSetupStep(step=state.setupStep){if(step===0){if(!$('#wTitle').value.trim())throw new Error('enterDashboardName')}if(step===1){const mode=$('#wAuthMode').value;if(mode!=='disabled'){if(!$('#wDashUser').value.trim())throw new Error('enterDashboardUsername');if(!$('#wDashPass').value)throw new Error('createDashboardPassword');if($('#wDashPass').value!==$('#wDashPass2').value)throw new Error('dashboardPasswordsDoNotMatch')}if(mode==='lan_bypass'&&!selectedInterfaceIds('#wInterfaceList').length&&!parseWhitelist('#wTrustedIps').length)throw new Error('selectTrustedInterfaceOrWhitelistIp')}if(step===2){if(!$('#wClientUrl').value.trim())throw new Error('enterQbittorrentWebUiUrl');if($('#wClientAuth').value==='api_key'){const key=$('#wClientApiKey').value.trim();if(!key)throw new Error('enterQbittorrentApiKey');if(!/^qbt_[A-Za-z0-9]{28}$/.test(key))throw new Error('invalidQbittorrentApiKeyFormat')}else{if(!$('#wClientUser').value.trim())throw new Error('enterQbittorrentUsername');if(!$('#wClientPass').value)throw new Error('enterQbittorrentPassword')}}if(step===3&&$('#wUpdatesEnabled').checked&&!$('#wUpdateRepo').value.trim())throw new Error('enterGitHubRepositoryForUpdates')}
function canJumpToSetupStep(target){if(target<=state.setupStep)return true;for(let i=state.setupStep;i<target;i++)validateSetupStep(i);return true}
function goToSetupStep(target){const max=$$('.setup-page').length-1;target=Math.max(0,Math.min(max,Number(target)));try{canJumpToSetupStep(target);state.setupStep=target;updateSetupStep()}catch(e){$('#setupError').textContent=e.message}}
function updateWizardClientAuth(){const api=$('#wClientAuth').value==='api_key';$('#wClientApiWrap').classList.toggle('hidden',!api);$('#wClientPasswordWrap').classList.toggle('hidden',api)}
function updateWizardLanVisibility(){$('#wLanTrust').classList.toggle('hidden',$('#wAuthMode').value!=='lan_bypass');$('#wizardAccount').classList.toggle('hidden',$('#wAuthMode').value==='disabled')}
function renderSetupReview(){const p=setupPayload(),mode={required:'requiredEverywhere',lan_bypass:'trustedAddressBypass',disabled:'disabled'}[p.auth.mode]||p.auth.mode,client=p.servers[0],clientAuth=client.auth_method==='api_key'?'apiKey':'usernameAndPassword',interfaceNames=p.auth.trusted_interfaces.length?p.auth.trusted_interfaces.join(', '):'none',whitelist=p.auth.trusted_ips.length?`${p.auth.trusted_ips.length} whitelistEntries`:'noWhitelistEntries';$('#wReview').innerHTML=`<div><span>dashboard</span><b>${esc(p.dashboard.title)}</b><small>0.0.0.0:${p.dashboard.port} · ${p.dashboard.refresh_seconds}s refresh</small></div><div><span>dashboardAccess</span><b>${esc(mode)}</b><small>${esc(interfaceNames)} · ${esc(whitelist)} · ${p.dashboard.read_only?'readOnly':'managementEnabled'}</small></div><div><span>downloadClient</span><b>${esc(client.name)}</b><small>${esc(client.base_url)}</small></div><div><span>qBittorrentAuthentication</span><b>${esc(clientAuth)}</b><small>${client.auth_method==='api_key'?'bearerApiKeyNoLoginCookie':esc(client.username)}</small></div><div><span>optionalFeatures</span><b>${state.setup?.dependencies?.qr?.installed?'qrSupportInstalled':'qrSupportOptional'}</b><small>Can be changed later under settings.</small></div><div><span>applicationUpdates</span><b>${p.updates.enabled?'githubUpdatesEnabled':'manualUpdates'}</b><small>${p.updates.enabled?esc(p.updates.repository):'Can be enabled later under settings.'}</small></div>`}
async function wizardTestClient(){const out=$('#wClientResult');out.className='test-result muted';out.textContent='testing…';try{validateSetupStep(2);const d=await rawJson('/api/setup/client-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({setup_code:$('#wSetupCode').value.trim(),server:setupServer()})});out.className='test-result ok';out.textContent=`connected · qBittorrent ${d.version||'unknown'} · webApi ${d.api_version||'unknown'} · ${d.auth_method==='api_key'?'apiKey':'password'}`}catch(e){out.className='test-result bad';out.textContent=e.message}}
async function finishSetup(){const err=$('#setupError'),btn=$('#wNext');try{for(let i=0;i<$$('.setup-page').length-1;i++)validateSetupStep(i);btn.disabled=true;btn.textContent='testingAndSaving…';err.textContent='';const d=await rawJson('/api/setup/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(setupPayload())});state.csrf=d.csrf||'';location.reload()}catch(e){err.textContent=e.message;btn.disabled=false;btn.textContent='finish'}}

async function bootstrap(){
  try{state.setup=await rawJson('/api/setup/status');if(state.setup.required){showSetup();$('#wUpdateRepo').value=state.setup?.updates?.repository||$('#wUpdateRepo').value||'CynicaGaming/TorrentDashboard';$('#wUpdatesEnabled').checked=state.setup?.updates?.enabled!==false;$('#wTrustedIps').value=(state.setup.trusted_ips||[]).join('\n');renderInterfaceList('#wInterfaceList',state.setup.network_interfaces||[],state.setup.trusted_interfaces||[],!(state.setup.trusted_interfaces||[]).length);state.setupInterfaceSelectionInitialized=true;renderDependencyStatus('#wDependencyList',state.setup.dependencies||{});$('#wDependencyResult').textContent=state.setup.dependencies?.qr?.installed?'qrSupportReady':'optionalDependenciesCanBeInstalledHere';$('#setupCodeWrap').classList.toggle('hidden',!state.setup.code_required);updateWizardClientAuth();updateWizardLanVisibility();updateSetupStep();return}state.me=await api('/api/me');state.csrf=state.me.csrf;showApp();$('#brandTitle').textContent=state.me.title;document.title=state.me.title;$('#version').textContent=`v${state.me.version}`;$('#lanUrl').textContent=`${state.me.scheme||'http'}://${state.me.lan_ip}:${state.me.port}`;await loadSettings();await loadServers();bindUI();applyPrefs();await refreshStatus();scheduleRefresh();registerPwa();setTimeout(maybeAutoCheckUpdates,1200);}
  catch(e){if(!$('#setup').classList.contains('hidden'))return;showLogin()}
}

async function login(e){e.preventDefault();$('#loginError').textContent='';try{const d=await rawJson('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#loginUser').value,password:$('#loginPass').value})});state.csrf=d.csrf;location.reload()}catch(err){$('#loginError').textContent=err.message}}
async function loadServers(){let d=await api('/api/servers');let sel=$('#serverSelect');sel.innerHTML='<option value="all">allServers</option>'+d.servers.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if(![...sel.options].some(o=>o.value===state.server))state.server='all';sel.value=state.server}
async function loadSettings(){try{state.settings=await api('/api/settings');fillSettings();loadSavedViews()}catch(e){toast(e.message,'error')}}
function fillSettings(){if(!state.settings)return;const s=state.settings;$('#sTitle').value=s.dashboard.title||'Torrent Desk';$('#sRefresh').value=s.dashboard.refresh_seconds||2;$('#sUpdatesEnabled').checked=!!s.updates?.enabled;$('#sUpdateRepo').value=s.updates?.repository||'CynicaGaming/TorrentDashboard';$('#sUpdateToken').value='';$('#sUpdateToken').placeholder=s.updates?.github_token==='<configured>'?'Token Configured — Leave Blank To Keep':'Fine-grained token with Contents: Read';$('#sUpdateAutoCheck').checked=s.updates?.auto_check!==false;$('#sUpdateHours').value=s.updates?.check_hours||6;renderUpdateInfo({configured:!!(s.updates?.repository||s.updates?.manifest_url),currentVersion:state.me?.version,state:s.runtime?.updateState||{}});$('#sUsername').value=s.auth.username||'admin';$('#sAuth').value=s.auth.mode;$('#sTrustedIps').value=(s.auth.trusted_ips||[]).join('\n');renderInterfaceList('#sInterfaceList',s.runtime?.network_interfaces||[],s.auth.trusted_interfaces||[],false);state.settingsInterfaceSelectionInitialized=true;updateQrState(s.runtime?.dependencies||{});$('#sReadOnly').checked=!!s.dashboard.read_only;$('#sTheme').value=localStorage.tdTheme||'dark';$('#sDensity').value=localStorage.tdDensity||'comfortable';$('#sAccent').value=localStorage.tdAccent||'#72a9ff';let cols=JSON.parse(localStorage.tdColumns||'{}');$$('[data-column]').forEach(x=>x.checked=cols[x.dataset.column]!==false);renderServerSettings(s.servers||[]);let n=s.notifications||{},i=s.integrations||{};$('#nWebhook').value=n.webhook_url||'';$('#nDiscord').value=n.discord_webhook||'';$('#nNtfy').value=n.ntfy_url||'';for(const name of ['sonarr','radarr','lidarr','prowlarr','jellyfin']){let cap=name[0].toUpperCase()+name.slice(1),v=i[name]||{};$('#i'+cap+'Url').value=v.url||'';$('#i'+cap+'Key').value=''}let pv=i.plex||{};$('#iPlexUrl').value=pv.url||'';$('#iPlexToken').value=''}
function renderUpdateInfo(data){state.updateInfo=data||null;const current=data?.currentVersion||state.me?.version||'—',manifest=data?.manifest||{},st=data?.state||state.settings?.runtime?.updateState||{};$('#updateCurrent').textContent=current;$('#updateLatest').textContent=manifest.version||st.version||uiText('notChecked');$('#updateState').textContent=uiText(st.state||'idle');const msg=$('#updateMessage');msg.className='muted update-message';let text='';if(data?.error){text=data.error;msg.classList.add('bad')}else if(data?.configured===false){text='updatesNotConfigured'}else if(data?.updateAvailable){text=`updateAvailable ${manifest.version}${manifest.publishedAt?` · ${manifest.publishedAt}`:''}`;msg.classList.add('ok')}else if(manifest.version){text=`upToDate ${current}`;msg.classList.add('ok')}else if(st.state&&st.state!=='idle'){text=st.error||st.state}else{text='checkForUpdatesWhenReady'}msg.textContent=data?.error?text:uiText(text);$('#downloadUpdate').disabled=!(data?.updateAvailable);$('#installUpdate').disabled=st.state!=='readyToInstall';if(st.state==='readyToInstall'){$('#installUpdate').disabled=false;$('#downloadUpdate').disabled=true}}
async function checkForUpdates(silent=false){try{const d=await api('/api/update-check');renderUpdateInfo(d);if(!silent&&d.updateAvailable)toast(`updateAvailable ${d.manifest.version}`);else if(!silent&&!d.error)toast(d.configured===false?'updatesNotConfigured':'updateCheckComplete');return d}catch(e){renderUpdateInfo({currentVersion:state.me?.version,error:e.message,state:state.settings?.runtime?.updateState||{}});if(!silent)toast(e.message,'error');throw e}}
async function downloadUpdate(){const b=$('#downloadUpdate');b.disabled=true;b.textContent=uiText('downloading…');try{const d=await post('/api/update-download',{});renderUpdateInfo({configured:true,currentVersion:state.me?.version,manifest:d.manifest,updateAvailable:true,state:d});toast('updateReadyToInstall')}catch(e){toast(e.message,'error')}finally{b.textContent=uiText('downloadUpdate');if(state.updateInfo)renderUpdateInfo(state.updateInfo)}}
async function installUpdate(){const version=state.updateInfo?.state?.version||state.settings?.runtime?.updateState?.version||$('#updateLatest').textContent;if(!confirm(`installAndRestart ${version}?`))return;const b=$('#installUpdate');b.disabled=true;b.textContent=uiText('restarting…');try{await post('/api/update-install',{version});$('#updateMessage').textContent=`${uiText('installing')} ${version} · ${uiText('torrentDeskWillRestart')}`;$('#updateState').textContent=uiText('installing');toast('installingUpdate');waitForUpdatedServer(version)}catch(e){b.disabled=false;b.textContent=uiText('installAndRestart');toast(e.message,'error')}}
function waitForUpdatedServer(version){const started=Date.now();const timer=setInterval(async()=>{if(Date.now()-started>60000){clearInterval(timer);$('#updateMessage').textContent=uiText('updateRestartTakingLongerThanExpected');return}try{const r=await fetch('/health',{cache:'no-store'});if(!r.ok)return;const d=await r.json();if(String(d.version)===String(version)){clearInterval(timer);location.reload()}}catch{}},1200)}
async function maybeAutoCheckUpdates(){if(!state.settings?.updates?.enabled||state.settings?.updates?.auto_check===false)return;const hours=Math.max(1,Number(state.settings.updates.check_hours||6)),last=Number(localStorage.tdLastUpdateCheck||0);if(Date.now()-last<hours*3600000)return;localStorage.tdLastUpdateCheck=Date.now();try{await checkForUpdates(true)}catch{}}

function updateQrState(deps){const installed=!!deps?.qr?.installed;$('#qr').classList.toggle('hidden',!installed);$('#qrFallback').classList.toggle('hidden',installed);if(installed){$('#qr').src='/api/qr?ts='+Date.now()}else{$('#qr').removeAttribute('src')}}
async function installQrFromSettings(){const b=$('#installQrSettings');b.disabled=true;b.textContent='installing…';try{const d=await post('/api/install-dependency',{feature:'qr'});updateQrState(d.status||{});toast('qrSupportInstalled')}catch(e){toast(e.message,'error')}finally{b.disabled=false;b.textContent='installQrSupport'}}

function setView(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('.nav,.mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#pageTitle').textContent=uiText(view==='history'?'transferHistory':view);$('#subtitle').textContent=uiText(view==='dashboard'?'liveTorrentActivity':view==='history'?'transferAndCompletionHistory':'dashboardConfiguration');if(view==='history')loadHistory();if(view==='settings'){loadSettings();loadIntegrations()}}
function scheduleRefresh(){clearInterval(state.timer);state.timer=setInterval(refreshStatus,state.refreshMs)}
async function refreshStatus(){try{let d=await api(`/api/status?server=${encodeURIComponent(state.server)}`);state.torrents=d.torrents||[];state.transfer=d.transfer||{};state.lastStatus=d;$('#errorBanner').classList.toggle('hidden',!(d.errors||[]).length);$('#errorBanner').textContent=(d.errors||[]).join(' · ');renderMetrics(d);renderFilters();render();detectCompletions();return d}catch(e){$('#errorBanner').textContent=e.message;$('#errorBanner').classList.remove('hidden')}}
function renderMetrics(d){const t=state.torrents,x=state.transfer,active=t.filter(isActive),queued=active.filter(a=>!Number(a.dlspeed)).length,remain=active.reduce((a,b)=>a+Number(b.amount_left||0),0),etas=active.map(a=>Number(a.eta)).filter(v=>Number.isFinite(v)&&v<8640000),avg=etas.length?etas.reduce((a,b)=>a+b,0)/etas.length:Infinity;$('#mDown').textContent=speed(x.dl_info_speed||0);$('#mDownTotal').textContent=`Session ${bytes(x.dl_info_data||0)}`;$('#mUp').textContent=speed(x.up_info_speed||0);$('#mUpTotal').textContent=`Session ${bytes(x.up_info_data||0)}`;$('#mActive').textContent=active.length;$('#mQueue').textContent=queued?`${queued} ${uiText('queuedOrStalled')}`:uiText('allActive');$('#mRemain').textContent=bytes(remain);$('#mEta').textContent=`${uiText('avgEta')} ${eta(avg)}`;$('#mUpdated').textContent=new Date((d.ts||Date.now()/1000)*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});$('#mHealth').textContent=uiText(d.ok===false?'connectionIssue':'healthy');let disk=d.disk_free;if(state.server==='all')disk=null;$('#mDisk').textContent=disk==null?'—':bytes(disk);let low=Number(state.settings?.dashboard?.low_disk_gb||20)*1024**3;$('#mDiskWarn').textContent=uiText(disk!=null&&disk<low?'lowDiskSpace':'downloadVolume');const c=d.tab_counts||{};$('#countAll').textContent=c.all??t.length;$('#countActive').textContent=c.downloading??t.filter(isActive).length;$('#countCompleted').textContent=c.completed??t.filter(isComplete).length;$('#countPaused').textContent=c.paused??t.filter(isPaused).length}
function isPaused(t){let s=String(t.state||'').toLowerCase();return s.includes('pause')||s.includes('stop')}
function isComplete(t){return Number(t.progress)>=.999999}
function isActive(t){return !isComplete(t)&&!isPaused(t)}
function stateInfo(t){const s=String(t.state||'').toLowerCase();if(s.includes('error')||s.includes('missing'))return['error','error'];if(isPaused(t))return['paused','pause'];if(s.includes('upload')||s.includes('seed'))return[Number(t.upspeed)>0?'seeding':'seedIdle','seed'];if(s.includes('stall')&&!isComplete(t))return['stalled','pause'];if(s.includes('check'))return['checking','pause'];if(s.includes('meta'))return['metadata','down'];if(!isComplete(t)&&Number(t.dlspeed)>0)return['downloading','down'];if(!isComplete(t))return['queued',''];return['complete','seed']}

function renderFilters(){const cats=new Set(),tags=new Set(),trackers=new Set();for(const t of state.torrents){if(t.category)cats.add(t.category);for(const x of String(t.tags||'').split(','))if(x.trim())tags.add(x.trim());if(t.tracker){try{trackers.add(new URL(t.tracker).hostname)}catch{trackers.add(t.tracker)}}}setOptions($('#category'),cats,'allCategories',state.category);setOptions($('#tag'),tags,'allTags',state.tag);setOptions($('#tracker'),trackers,'allTrackers',state.tracker)}
function setOptions(el,set,all,current){const old=el.value;el.innerHTML=`<option value="">${all}</option>`+[...set].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');el.value=[...el.options].some(o=>o.value===current)?current:''}
function filtered(){let q=state.search.toLowerCase();let a=state.torrents.filter(t=>{if(state.filter==='active'&&!isActive(t))return false;if(state.filter==='completed'&&!isComplete(t))return false;if(state.filter==='paused'&&!isPaused(t))return false;if(q&&!`${t.name} ${t.category||''} ${t.tags||''} ${t.tracker||''}`.toLowerCase().includes(q))return false;if(state.category&&t.category!==state.category)return false;if(state.tag&&!String(t.tags||'').split(',').map(x=>x.trim()).includes(state.tag))return false;if(state.tracker){let h=t.tracker;try{h=new URL(t.tracker).hostname}catch{}if(h!==state.tracker)return false}return true});let [k,dir]=state.sort.split('_');a.sort((x,y)=>{let A=k==='name'?String(x.name).toLowerCase():Number(x[k]??0),B=k==='name'?String(y.name).toLowerCase():Number(y[k]??0);return(A>B?1:A<B?-1:0)*(dir==='asc'?1:-1)});return a}
function rowKey(t){return`${t.server_id}:${t.hash}`}
function render(){const list=filtered();$('#rows').innerHTML=list.map(t=>{let [label,cls]=stateInfo(t),pct=Math.max(0,Math.min(100,Number(t.progress||0)*100)),checked=state.selected.has(rowKey(t));return`<tr data-server="${esc(t.server_id)}" data-hash="${esc(t.hash)}"><td class="check-col"><input class="row-check" type="checkbox" ${checked?'checked':''}></td><td class="name-col"><div class="torrent-name" title="${esc(t.name)}">${esc(t.name)}</div><div class="torrent-meta">${esc(t.server_name||'')} · ${bytes(t.size)}${t.category?` · ${esc(t.category)}`:''}</div></td><td data-col="progress" class="progress"><div class="progress-top"><span>${pct.toFixed(1)}%</span><span>${bytes(t.amount_left)} left</span></div><div class="track"><div class="fill" style="width:${pct}%"></div></div></td><td data-col="state"><span class="state-pill ${cls}">${esc(uiText(label))}</span></td><td data-col="down" class="mono">${speed(t.dlspeed||0)}</td><td data-col="up" class="mono">${speed(t.upspeed||0)}</td><td data-col="eta" class="mono">${eta(t.eta)}</td><td data-col="ratio" class="mono">${Number(t.ratio||0).toFixed(2)}</td></tr>`}).join('');$('#mobileCards').innerHTML=list.map(cardHtml).join('');$('#empty').classList.toggle('hidden',!!list.length);renderSelection();applyColumnPrefs()}
function cardHtml(t){let [label,cls]=stateInfo(t),pct=Number(t.progress||0)*100,checked=state.selected.has(rowKey(t));return`<article class="torrent-card" data-server="${esc(t.server_id)}" data-hash="${esc(t.hash)}"><div class="card-head"><input class="row-check" type="checkbox" ${checked?'checked':''}><div class="card-name"><b>${esc(t.name)}</b><small>${esc(t.server_name||'')} · ${bytes(t.size)}</small></div><span class="state-pill ${cls}">${esc(uiText(label))}</span></div><div class="card-progress"><div><span>${pct.toFixed(1)}%</span><span>${bytes(t.amount_left)} left</span></div><div class="track"><div class="fill" style="width:${pct}%"></div></div></div><div class="card-grid"><div><span>download</span><strong>${speed(t.dlspeed||0)}</strong></div><div><span>upload</span><strong>${speed(t.upspeed||0)}</strong></div><div><span>ETA</span><strong>${eta(t.eta)}</strong></div><div><span>ratio</span><strong>${Number(t.ratio||0).toFixed(2)}</strong></div></div></article>`}
function renderSelection(){let n=state.selected.size;$('#selectionBar').classList.toggle('hidden',!n);$('#selectedCount').textContent=`${n} selected`;}
function detectCompletions(){for(const t of state.torrents){let k=rowKey(t),done=isComplete(t);if(done&&!state.lastComplete.has(k)&&state.lastComplete.size){notify(`${t.name} completed`);beep()}if(done)state.lastComplete.add(k)}}
function notify(body){if(Notification?.permission==='granted')new Notification('Torrent Desk',{body})}

function bindUI(){
  $$('.nav,.mobile-nav button').forEach(b=>b.onclick=()=>setView(b.dataset.view));
  $('#serverSelect').onchange=e=>{state.server=e.target.value;state.selected.clear();refreshStatus()};
  $('#tabs').onclick=e=>{let b=e.target.closest('[data-filter]');if(!b)return;state.filter=b.dataset.filter;localStorage.tdFilter=state.filter;$$('#tabs button').forEach(x=>x.classList.toggle('active',x===b));render()};
  $('#search').value=state.search;$('#search').oninput=e=>{state.search=e.target.value;localStorage.tdSearch=state.search;render()};
  for(const id of ['category','tag','tracker'])$('#'+id).onchange=e=>{state[id]=e.target.value;localStorage['td'+id[0].toUpperCase()+id.slice(1)]=state[id];render()};
  $('#sort').value=state.sort;$('#sort').onchange=e=>{state.sort=e.target.value;localStorage.tdSort=state.sort;render()};
  $('#torrentTable').onclick=tableClick;$('#mobileCards').onclick=tableClick;$('#torrentTable').oncontextmenu=context;$('#mobileCards').oncontextmenu=context;
  $('#selectAll').onchange=e=>{for(const t of filtered()){let k=rowKey(t);e.target.checked?state.selected.add(k):state.selected.delete(k)}render()};
  $('#clearSelection').onclick=()=>{state.selected.clear();render()};$('#bulkPause').onclick=()=>bulk('pause');$('#bulkResume').onclick=()=>bulk('resume');$('#bulkDelete').onclick=()=>bulkDelete();
  $('#addBtn').onclick=()=>{if(state.server==='all')return toast('chooseSpecificServerFirst','error');$('#addModal').classList.remove('hidden')};$$('[data-modalclose]').forEach(b=>b.onclick=()=>$('#addModal').classList.add('hidden'));$('#addForm').onsubmit=addTorrent;
  $('#moreBtn').onclick=e=>{$('#menu').classList.toggle('hidden');e.stopPropagation()};document.addEventListener('click',()=>{$('#menu').classList.add('hidden');$('#contextMenu').classList.add('hidden')});
  $('#pauseAll').onclick=()=>globalAction('pause_all');$('#resumeAll').onclick=()=>globalAction('resume_all');$('#altSpeed').onclick=()=>globalAction('toggle_alt_speed');$('#globalDl').onclick=()=>globalLimit('set_global_dl');$('#globalUl').onclick=()=>globalLimit('set_global_up');
  $('#notifyPermission').onclick=()=>Notification?.requestPermission();
  $$('[data-close]').forEach(x=>x.onclick=()=>$('#drawer').classList.add('hidden'));$$('[data-detailtab]').forEach(x=>x.onclick=()=>{state.detailTab=x.dataset.detailtab;$$('[data-detailtab]').forEach(y=>y.classList.toggle('active',y===x));loadDetail()});
  $('#settingsForm').onsubmit=saveSettings;$('#addServerSetting').onclick=()=>addServerRow();$('#testNotify').onclick=async()=>{await post('/api/test-notification',{});toast('testNotificationSent')};$('#copyLan').onclick=()=>navigator.clipboard.writeText($('#lanUrl').textContent).then(()=>toast('lanUrlCopied'));
  $('#historyRange').onchange=loadHistory;$('#saveView').onclick=saveCurrentView;$('#savedView').onchange=applySavedView;
  $('#sRefreshInterfaces').onclick=()=>refreshSettingsInterfaces(true).catch(e=>toast(e.message,'error'));
  $('#installQrSettings').onclick=installQrFromSettings;
  $('#checkUpdate').onclick=()=>checkForUpdates(false);$('#downloadUpdate').onclick=downloadUpdate;$('#installUpdate').onclick=installUpdate;
}

$('#setupForm').addEventListener('submit',e=>e.preventDefault());
$('#wBack').onclick=()=>goToSetupStep(state.setupStep-1);
$('#wNext').onclick=()=>{const last=$$('.setup-page').length-1;if(state.setupStep===last)return finishSetup();try{validateSetupStep();goToSetupStep(state.setupStep+1)}catch(e){$('#setupError').textContent=e.message}};
$('#setupSteps').onclick=e=>{const b=e.target.closest('[data-setup-step]');if(b)goToSetupStep(Number(b.dataset.setupStep))};
$('#wTestClient').onclick=wizardTestClient;$('#wClientAuth').onchange=updateWizardClientAuth;$('#wAuthMode').onchange=updateWizardLanVisibility;$('#wRefreshInterfaces').onclick=()=>refreshSetupInterfaces(true).catch(e=>$('#setupError').textContent=e.message);$('#wInstallQr').onclick=()=>installSetupDependency('qr');$('#wInstallAll').onclick=()=>installSetupDependency('all');
$('#loginForm').onsubmit=login;

function tableClick(e){let check=e.target.closest('.row-check'),tr=e.target.closest('[data-hash]');if(!tr)return;let k=`${tr.dataset.server}:${tr.dataset.hash}`;if(check){check.checked?state.selected.add(k):state.selected.delete(k);renderSelection();return}openDetail(tr.dataset.server,tr.dataset.hash)}
function context(e){let tr=e.target.closest('[data-hash]');if(!tr)return;e.preventDefault();let t=state.torrents.find(x=>x.hash===tr.dataset.hash&&x.server_id===tr.dataset.server);if(!t)return;let m=$('#contextMenu');m.style.left=Math.min(e.clientX,innerWidth-210)+'px';m.style.top=Math.min(e.clientY,innerHeight-280)+'px';m.style.right='auto';m.innerHTML=contextButtons(t);m.classList.remove('hidden');m.onclick=x=>{let b=x.target.closest('[data-act]');if(b)detailAction(t,b.dataset.act)}}
function contextButtons(t){return`<button data-act="${isPaused(t)?'resume':'pause'}">${isPaused(t)?'Resume':'Pause'}</button><button data-act="force_start">Force start</button><button data-act="recheck">Recheck</button><button data-act="reannounce">Reannounce</button><button data-act="increase">Move up</button><button data-act="decrease">Move down</button><button data-act="delete">Delete…</button>`}

async function openDetail(server,hash){state.detail={server,hash,t:state.torrents.find(x=>x.server_id===server&&x.hash===hash)};state.detailTab='overview';$$('[data-detailtab]').forEach(x=>x.classList.toggle('active',x.dataset.detailtab==='overview'));$('#drawer').classList.remove('hidden');$('#detailName').textContent=state.detail.t?.name||hash;$('#detailMeta').textContent=`${state.detail.t?.server_name||server} · ${hash}`;renderDetailActions();loadDetail()}
function renderDetailActions(){let t=state.detail?.t;if(!t)return;$('#detailActions').innerHTML=`<button data-act="${isPaused(t)?'resume':'pause'}">${isPaused(t)?'Resume':'Pause'}</button><button data-act="force_start">Force start</button><button data-act="recheck">Recheck</button><button data-act="reannounce">Reannounce</button><button data-act="sequential">Sequential</button><button data-act="first_last">First/last priority</button><button data-act="top">Top</button><button data-act="bottom">Bottom</button><button data-act="delete" class="danger">Delete</button>`;$('#detailActions').onclick=e=>{let b=e.target.closest('[data-act]');if(b)detailAction(t,b.dataset.act)}}
async function loadDetail(){if(!state.detail)return;$('#detailBody').innerHTML='<div class="empty">Loading…</div>';try{let d=await api(`/api/detail?server=${encodeURIComponent(state.detail.server)}&hash=${state.detail.hash}&tab=${state.detailTab}`);renderDetail(d.data)}catch(e){$('#detailBody').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderDetail(d){if(state.detailTab==='overview'){let t=state.detail.t,p=d||{};let kv={totalSize:bytes(p.total_size||t.size),downloaded:bytes(p.total_downloaded||t.downloaded),uploaded:bytes(p.total_uploaded||t.uploaded),shareRatio:Number(t.ratio||0).toFixed(2),savePath:p.save_path||t.save_path||'—',createdBy:p.created_by||'—',added:when(t.added_on),completed:when(t.completion_on),seedingTime:eta(p.seeding_time),timeActive:eta(p.time_elapsed),connections:p.nb_connections??'—',pieces:p.pieces_num??'—',pieceSize:bytes(p.piece_size)};$('#detailBody').innerHTML=`<div class="kv">${Object.entries(kv).map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`;return}if(state.detailTab==='files'){let files=Array.isArray(d)?d:[];$('#detailBody').innerHTML=`<div class="detail-list">${files.map(f=>`<div class="detail-row"><span>${esc(f.name)}</span><span>${(Number(f.progress)*100).toFixed(1)}%</span><select data-file="${f.index}"><option value="0" ${f.priority===0?'selected':''}>Skip</option><option value="1" ${f.priority===1?'selected':''}>Normal</option><option value="6" ${f.priority===6?'selected':''}>High</option><option value="7" ${f.priority===7?'selected':''}>Max</option></select></div>`).join('')}</div>`;$$('[data-file]').forEach(x=>x.onchange=()=>doAction('file_priority',{hashes:state.detail.hash,ids:[Number(x.dataset.file)],priority:Number(x.value)},state.detail.server));return}if(state.detailTab==='peers'){let peers=Object.values(d?.peers||{});$('#detailBody').innerHTML=`<div class="detail-list">${peers.map(p=>`<div class="detail-row"><span>${esc(p.ip)} · ${esc(p.client||'')}</span><span>${(Number(p.progress||0)*100).toFixed(1)}%</span><span>${speed(p.dl_speed||0)}</span></div>`).join('')}</div>`;return}if(state.detailTab==='trackers'){let a=Array.isArray(d)?d:[];$('#detailBody').innerHTML=`<div class="detail-list">${a.map(t=>`<div class="detail-row"><span>${esc(t.url)}</span><span>${esc(t.msg||'')}</span><span>${t.num_peers??'—'} peers</span></div>`).join('')}</div>`;return}if(state.detailTab==='pieces'){let a=Array.isArray(d)?d:[];$('#detailBody').innerHTML=`<div class="piece-map">${a.map(x=>`<i class="piece ${x===2?'ok':''}" title="${x}"></i>`).join('')}</div>`}}

async function detailAction(t,act){if(act==='delete'){let files=confirm('Delete downloaded files too?');if(!confirm(`Delete ${t.name}?`))return;return doAction('delete',{hashes:t.hash,delete_files:files},t.server_id)}if(act==='force_start')return doAction('force_start',{hashes:t.hash,value:!t.force_start},t.server_id);return doAction(act,{hashes:t.hash},t.server_id)}
async function doAction(action,payload={},server=state.server){if(state.settings?.dashboard?.read_only)return toast('dashboardIsReadOnly','error');try{await post('/api/action',{server,action,...payload});toast('actionSent');setTimeout(refreshStatus,250);if(state.detail)loadDetail()}catch(e){toast(e.message,'error')}}
async function bulk(action){let groups={};for(const k of state.selected){let i=k.indexOf(':'),s=k.slice(0,i),h=k.slice(i+1);(groups[s]??=[]).push(h)}for(const [s,h] of Object.entries(groups))await doAction(action,{hashes:h},s);state.selected.clear();render()}
async function bulkDelete(){if(!confirm(`Delete ${state.selected.size} selected torrents?`))return;let files=confirm('Delete downloaded files too?');let groups={};for(const k of state.selected){let i=k.indexOf(':'),s=k.slice(0,i),h=k.slice(i+1);(groups[s]??=[]).push(h)}for(const [s,h] of Object.entries(groups))await doAction('delete',{hashes:h,delete_files:files},s);state.selected.clear();render()}
async function globalAction(action){if(state.server==='all')return toast('chooseSpecificServerForAction','error');doAction(action,{},state.server)}

async function addTorrent(e){e.preventDefault();if(state.server==='all')return toast('chooseSpecificServerFirst','error');try{const f=$('#torrentFile').files[0];if(f){let fd=new FormData();fd.append('server',state.server);fd.append('savepath',$('#addPath').value);fd.append('category',$('#addCategory').value);fd.append('tags',$('#addTags').value);fd.append('stopped',String($('#addStopped').checked));fd.append('sequentialDownload',String($('#addSequential').checked));fd.append('firstLastPiecePrio',String($('#addFirstLast').checked));fd.append('torrents',f);await api('/api/upload',{method:'POST',headers:{'X-CSRF-Token':state.csrf},body:fd})}else{if(!$('#addUrls').value.trim())throw new Error('pasteMagnetUrlOrChooseTorrentFile');await post('/api/action',{server:state.server,action:'add_magnet',urls:$('#addUrls').value.trim(),savepath:$('#addPath').value,category:$('#addCategory').value,tags:$('#addTags').value,stopped:$('#addStopped').checked,sequential:$('#addSequential').checked,first_last:$('#addFirstLast').checked})}$('#addModal').classList.add('hidden');$('#addForm').reset();toast('torrentAdded');setTimeout(refreshStatus,500)}catch(err){toast(err.message,'error')}}

async function loadHistory(){try{const min=$('#historyRange').value,[h,a,e]=await Promise.all([api(`/api/history?server=${encodeURIComponent(state.server)}&minutes=${min}`),api(`/api/analytics?server=${encodeURIComponent(state.server)}`),api('/api/events?limit=100')]);$('#aAvg').textContent=speed(a.avg_dl_7d);$('#aPeak').textContent=speed(a.peak_dl_7d);$('#aKnown').textContent=a.known_torrents;$('#aComplete').textContent=a.completed;drawChart(h.points||[]);$('#eventList').innerHTML=(e.events||[]).map(x=>`<div class="event"><div><b>${esc(x.name||x.event)}</b><small>${esc(x.server_id||'')} · ${esc(x.event)}</small></div><small>${rel(x.ts)}</small></div>`).join('')||`<div class="empty">${uiText('noRecordedEventsYet')}</div>`}catch(err){toast(err.message,'error')}}
function drawChart(points){const c=$('#speedChart'),ctx=c.getContext('2d'),ratio=devicePixelRatio||1,w=c.clientWidth,h=220;c.width=w*ratio;c.height=h*ratio;ctx.scale(ratio,ratio);ctx.clearRect(0,0,w,h);if(!points.length){ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--muted');ctx.fillText(uiText('noHistoryCollectedYet'),15,25);return}let max=Math.max(1,...points.flatMap(p=>[Number(p.dl||0),Number(p.up||0)])),pad=20;ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--border');ctx.lineWidth=1;for(let i=0;i<4;i++){let y=pad+(h-pad*2)*i/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-pad,y);ctx.stroke()}function line(key,color){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();points.forEach((p,i)=>{let x=pad+(w-pad*2)*(i/(points.length-1||1)),y=h-pad-(h-pad*2)*Number(p[key]||0)/max;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}let st=getComputedStyle(document.documentElement);line('dl',st.getPropertyValue('--accent'));line('up',st.getPropertyValue('--good'))}

function renderServerSettings(servers){$('#serverSettings').innerHTML='';servers.forEach(s=>addServerRow(s))}
function addServerRow(s={id:'',name:'',base_url:'http://127.0.0.1:8080',auth_method:'api_key',api_key:'',username:'',password:'',enabled:true}){const d=document.createElement('div');d.className='server-setting';const method=s.auth_method||((s.api_key&&s.api_key!=='')?'api_key':'password');d.innerHTML=`<label>displayName<input data-k="name" placeholder="desktop" value="${esc(s.name||'')}"></label><label class="server-url">webUiUrl<input data-k="base_url" placeholder="http://127.0.0.1:8080" value="${esc(s.base_url||'')}"></label><label>authentication<select data-k="auth_method"><option value="api_key" ${method==='api_key'?'selected':''}>apiKey</option><option value="password" ${method==='password'?'selected':''}>usernameAndPassword</option></select></label><div class="server-auth-api"><label>apiKey<input data-k="api_key" type="password" autocomplete="off" placeholder="${s.api_key==='<configured>'?'apiKeyConfigured':'qbt_…'}"></label><small>qBittorrent 5.2+ · bearerAuthentication</small></div><div class="server-auth-password two"><label>username<input data-k="username" autocomplete="off" value="${esc(s.username||'')}"></label><label>password<input data-k="password" type="password" autocomplete="off" placeholder="${s.password==='<configured>'?'passwordConfigured':'password'}"></label></div><div class="server-setting-actions"><button type="button" class="test-server">test</button><button type="button" class="danger">remove</button></div><input type="hidden" data-k="id" value="${esc(s.id||'')}"><small class="server-test-result"></small>`;const sync=()=>{const useApi=d.querySelector('[data-k="auth_method"]').value==='api_key';d.querySelector('.server-auth-api').classList.toggle('hidden',!useApi);d.querySelector('.server-auth-password').classList.toggle('hidden',useApi)};d.querySelector('[data-k="auth_method"]').addEventListener('change',sync);sync();d.querySelector('.danger').onclick=()=>d.remove();d.querySelector('.test-server').onclick=()=>testServerRow(d);$('#serverSettings').append(d)}
function serverRowData(r){let o={enabled:true};r.querySelectorAll('[data-k]').forEach(i=>o[i.dataset.k]=i.value);return o}
async function testServerRow(r){const out=r.querySelector('.server-test-result');out.textContent=uiText('testing…');out.className='server-test-result';try{const d=await post('/api/client-test',serverRowData(r));out.textContent=`connected · qBittorrent ${d.version||'unknown'} · webApi ${d.api_version||'unknown'} · ${serverRowData(r).auth_method==='api_key'?'API Key':'Password'}`;out.className='server-test-result ok'}catch(e){out.textContent=e.message;out.className='server-test-result bad'}}
async function saveSettings(e){e.preventDefault();if($('#sPassword').value!==$('#sPassword2').value)return toast('dashboardPasswordsDoNotMatch','error');let servers=$$('.server-setting').map(serverRowData);let payload={dashboard:{title:$('#sTitle').value,refresh_seconds:Number($('#sRefresh').value),read_only:$('#sReadOnly').checked},updates:{enabled:$('#sUpdatesEnabled').checked,repository:$('#sUpdateRepo').value.trim(),github_token:$('#sUpdateToken').value.trim()||'<configured>',auto_check:$('#sUpdateAutoCheck').checked,check_hours:Number($('#sUpdateHours').value||6)},auth:{mode:$('#sAuth').value,username:$('#sUsername').value.trim()||'admin',trusted_interfaces:selectedInterfaceIds('#sInterfaceList'),trusted_ips:parseWhitelist('#sTrustedIps'),new_password:$('#sPassword').value},servers,notifications:{webhook_url:$('#nWebhook').value,discord_webhook:$('#nDiscord').value,ntfy_url:$('#nNtfy').value},integrations:{sonarr:{url:$('#iSonarrUrl').value,api_key:$('#iSonarrKey').value||'<configured>'},radarr:{url:$('#iRadarrUrl').value,api_key:$('#iRadarrKey').value||'<configured>'},lidarr:{url:$('#iLidarrUrl').value,api_key:$('#iLidarrKey').value||'<configured>'},prowlarr:{url:$('#iProwlarrUrl').value,api_key:$('#iProwlarrKey').value||'<configured>'},jellyfin:{url:$('#iJellyfinUrl').value,api_key:$('#iJellyfinKey').value||'<configured>'},plex:{url:$('#iPlexUrl').value,token:$('#iPlexToken').value||'<configured>'}}};try{let d=await post('/api/settings',payload);state.settings=d.settings;localStorage.tdTheme=$('#sTheme').value;localStorage.tdDensity=$('#sDensity').value;localStorage.tdAccent=$('#sAccent').value;let cols={};$$('[data-column]').forEach(x=>cols[x.dataset.column]=x.checked);localStorage.tdColumns=JSON.stringify(cols);applyPrefs();state.refreshMs=Math.max(1000,Number(state.settings.dashboard.refresh_seconds||2)*1000);scheduleRefresh();$('#sPassword').value='';$('#sPassword2').value='';toast('settingsSaved');await loadServers();await refreshStatus()}catch(err){toast(err.message,'error')}}

async function loadIntegrations(){try{const d=await api('/api/integrations');$('#integrationStatus').innerHTML=Object.entries(d).map(([k,v])=>`<div class="integration-card ${v.configured?(v.ok?'ok':'bad'):''}"><b>${esc(k)}</b><span>${!v.configured?uiText('notConfigured'):v.ok?uiText('connected'):esc(v.error||'error')}</span></div>`).join('')}catch(e){toast(e.message,'error')}}

function loadSavedViews(){let views=JSON.parse(localStorage.tdSavedViews||'{}'),sel=$('#savedView');sel.innerHTML=`<option value="">${uiText('savedViews')}</option>`+Object.keys(views).map(n=>`<option>${esc(n)}</option>`).join('')}
function saveCurrentView(){let name=prompt('Name This View:');if(!name)return;let views=JSON.parse(localStorage.tdSavedViews||'{}');views[name]={filter:state.filter,search:state.search,category:state.category,tag:state.tag,tracker:state.tracker,sort:state.sort};localStorage.tdSavedViews=JSON.stringify(views);loadSavedViews();toast('viewSaved')}
function applySavedView(e){let v=JSON.parse(localStorage.tdSavedViews||'{}')[e.target.value];if(!v)return;Object.assign(state,v);localStorage.tdFilter=state.filter;localStorage.tdSearch=state.search;localStorage.tdCategory=state.category;localStorage.tdTag=state.tag;localStorage.tdTracker=state.tracker;localStorage.tdSort=state.sort;$('#search').value=state.search;$('#sort').value=state.sort;$$('#tabs button').forEach(b=>b.classList.toggle('active',b.dataset.filter===state.filter));render()}
async function globalLimit(action){if(state.server==='all')return toast('chooseSpecificServerFirst','error');let kb=prompt('Limit KB Per Second (0 = Unlimited):','0');if(kb!==null)await doAction(action,{limit:Number(kb)*1024})}

function applyColumnPrefs(){let cols=JSON.parse(localStorage.tdColumns||'{}');for(const k of ['progress','state','down','up','eta','ratio'])$('#torrentTable')?.classList.toggle('hide-col-'+k,cols[k]===false)}
function applyPrefs(){let theme=localStorage.tdTheme||'dark';if(theme==='system')theme=matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';document.body.classList.toggle('light',theme==='light');document.body.classList.toggle('compact',(localStorage.tdDensity||'comfortable')==='compact');document.documentElement.style.setProperty('--accent',localStorage.tdAccent||'#72a9ff');applyColumnPrefs()}

function registerPwa(){if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredPrompt=e;$('#installPwa').classList.remove('hidden')});$('#installPwa').onclick=async()=>{if(state.deferredPrompt){state.deferredPrompt.prompt();await state.deferredPrompt.userChoice;state.deferredPrompt=null;$('#installPwa').classList.add('hidden')}}}

applyTitleCaseUi(document);titleObserver.observe(document.body,{childList:true,subtree:true});bootstrap();
